function t(key, values = {}) {
  const language = (typeof window !== 'undefined' && window.preferences && window.preferences.language) || 'ru';
  const table = (translations[language] || translations.ru || {});
  let result = table[key] || (translations.en && translations.en[key]) || key;
  Object.entries(values || {}).forEach(([name, value]) => {
    result = result.replaceAll(`{${name}}`, String(value));
  });
  return result;
}

// Classic-script mode: expose for app.js.
window.__vortexI18n = { translations, t };
